#working-table tbody tr.selected { background: var(--accent-soft); box-shadow: inset 2px 0 0 var(--accent); }
.status-dot { display: inline-block; width: 7px; height: 7px; border-radius: 4px; margin-right: 5px; vertical-align: 1px; }
.status-ok { background: var(--good); }
.status-degraded { background: var(--warn); }
.status-fail { background: var(--bad); }

#empty-state {
  flex: 1; display: flex; flex-direction: column;
  align-items: center; justify-content: center; gap: 2px;
  text-align: center; padding: 20px;
}
#empty-state p { margin: 2px 0; }
#btn-empty-clear { margin-top: 8px; color: var(--accent-ink); border-color: var(--accent-mid); font-weight: 600; }
.muted { color: var(--ink-3); }

/* ---------- inspector ---------- */
#inspector-body { overflow-y: auto; padding: 8px 10px; flex: 1; }
.insp-id { font-size: 14px; font-weight: 700; display: flex; align-items: center; gap: 7px; }
.insp-state { margin: 4px 0 10px; font-size: 11px; }
.insp-state.visible { color: var(--good); }
.insp-state.outside { color: var(--warn); }
.insp-dim { padding: 5px 0; border-bottom: 1px solid var(--line); }
.insp-dim .row1 { display: flex; justify-content: space-between; gap: 8px; }
.insp-dim .lab { color: var(--ink-3); font-size: 11px; }
.insp-dim .val { font-weight: 600; font-variant-numeric: tabular-nums; }
.insp-dim .val small { color: var(--ink-3); font-weight: 400; }
.insp-dim.out-filter .val { color: var(--warn); }
.insp-dim.out-filter .flag { color: var(--warn); font-size: 10px; margin-left: 6px; font-weight: 400; }
.inl-bar { height: 3px; background: #e8ecf2; border-radius: 2px; margin-top: 4px; }
.inl-bar i { display: block; height: 100%; border-radius: 2px; background: var(--accent-mid); }
.insp-dim.out-filter .inl-bar i { background: #e0aa59; }
.insp-hint { color: var(--ink-3); padding: 14px 4px; text-align: center; }

/* ---------- ledger ---------- */
#ledger {
  display: grid;
  grid-template-columns: minmax(320px, 46%) minmax(0, 1fr);
  gap: 8px;
  padding: 0 8px 8px;
  min-height: 0;
}
.ledger-zone { padding: 0; }
.ledger-zone .panel-head { border-bottom: none; padding-bottom: 2px; }
#filter-chips, #history-list { overflow-y: auto; padding: 2px 8px 8px; min-height: 0; flex: 1; }
#filter-chips { display: flex; flex-wrap: wrap; gap: 5px; align-content: flex-start; }

.chip {
  display: inline-flex; align-items: center; gap: 6px;
  background: var(--accent-soft);
  border: 1px solid var(--accent-mid);
  color: var(--accent-ink);
  border-radius: 20px;
  padding: 2px 4px 2px 10px;
  font-size: 11.5px;
  white-space: nowrap;
}
.chip .chip-owner { font-weight: 700; }
.chip .chip-pred { font-variant-numeric: tabular-nums; }
.chip-x {
  border: none; background: none;
  width: 17px; height: 17px; padding: 0;
  border-radius: 50%;
  display: inline-flex; align-items: center; justify-content: center;
  color: var(--accent-ink); font-weight: 700; font-size: 12px;
}
.chip-x:hover { background: var(--accent); color: #fff; }
.chip.lens-chip { background: #fff; border-color: var(--line-strong); color: var(--ink-2); }
.chip.lens-chip .chip-x { color: var(--ink-2); }
.chip.lens-chip .chip-x:hover { background: var(--ink-2); color: #fff; }
.ledger-empty { color: var(--ink-3); padding: 4px 2px; }

.hist-row {
  display: flex; align-items: center; gap: 7px;
  padding: 2.5px 2px;
  border-bottom: 1px dashed var(--line);
  font-size: 11.5px;
}
.hist-row .hist-kind {
  flex: none;
  font-size: 9.5px; font-weight: 700; letter-spacing: 0.4px;
  border-radius: 4px; padding: 1px 5px;
}
.hist-kind.filter-add { background: #e2f3e9; color: var(--good); }
.hist-kind.filter-remove { background: #fbe7e5; color: var(--bad); }
.hist-kind.filter-set { background: var(--accent-soft); color: var(--accent-ink); }
.hist-kind.lens { background: #efe9fb; color: #5b3ba8; }
.hist-kind.reset { background: #eceff3; color: var(--ink-2); }
.hist-row .hist-label { flex: 1; min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; color: var(--ink-2); }
.hist-row button { flex: none; padding: 1px 8px; font-size: 10.5px; }
.hist-row.spent { opacity: 0.45; }

input.content:
/*
 * Lensboard — dimensional workbench (cell-j13-s10 · explore × dimensional-space)
 *
 * State ownership (acceptance seed: 过滤/投影状态有归属且可回退):
 *   query      → per-dimension filter map (each filter belongs to exactly one dimension)
 *   viewport   → projection controller (the active lens), independent of query state
 *   selection  → working-set table + inspector pair, persists across lens switches
 *   preview    → lens chart hover/focus tooltip
 *   mode       → history ledger: every mutation is a labeled, invertible entry
 *
 * Switching the lens never touches the filter map: cognition carries across switches.
 */
'use strict';
(function () {
  const DS = window.DATASET;
  const DIMS = DS.dimensions;
  const INITIAL_LENS = 'temp_c';
  const NUM_BINS = 12;

  // ---------- tiny DOM helpers ----------
  const $ = (sel) => document.querySelector(sel);
  function h(tag, attrs, children) {
    const node = document.createElement(tag);
    if (attrs) for (const [k, v] of Object.entries(attrs)) {
      if (k === 'class') node.className = v;
      else if (k === 'text') node.textContent = v;
      else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else if (v !== false && v != null) node.setAttribute(k, v === true ? '' : v);
    }
    (children || []).forEach((c) => node.appendChild(c));
    return node;
  }
  const fmtVal = (dim, v) => v.toFixed(dim.dp || 0);

  // ---------- dataset statistics (computed once over the FULL dataset — stable anchors) ----------
  const STATS = {};
  for (const d of DIMS) {
    if (d.type === 'numeric') {
      let min = Infinity, max = -Infinity;
      for (const r of DS.records) { const v = r[d.id]; if (v < min) min = v; if (v > max) max = v; }
      const span = (max - min) || 1;
      const w = span / NUM_BINS;
      const bins = [];
      for (let i = 0; i < NUM_BINS; i++) bins.push({ lo: min + i * w, hi: min + (i + 1) * w, last: i === NUM_BINS - 1 });
      STATS[d.id] = { min, max, bins };
    } else {
      STATS[d.id] = { values: d.values.slice() };
    }
  }
  const binOf = (dim, v) => {
    const s = STATS[dim.id];
    let i = Math.floor((v - s.min) / ((s.max - s.min) || 1));
    if (i < 0) i = 0; if (i >= NUM_BINS) i = NUM_BINS - 1;
    return i;
  };

  // ---------- state ----------
  const state = {
    lens: INITIAL_LENS,                  // viewport owner
    sort: { dim: INITIAL_LENS, dir: 1 }, // reading order follows the lens
    filters: new Map(),                  // query owner: dimId -> {lo,hi} | {allowed:Set<string>}
    selection: null,                     // selection owner
    history: [],                         // mode owner: labeled invertible entries
  };

  const dimLabel = (id) => DIMS.find((d) => d.id === id).label;
  const dimOf = (id) => DIMS.find((d) => d.id === id);

  // ---------- query ----------
  function matchDim(record, dim, f) {
    const v = record[dim.id];
    if (dim.type === 'numeric') return v >= f.lo && (f.last ? v <= f.hi : v < f.hi);
    return f.allowed.has(v);
  }
  function inWorkingSet(record) {
    for (const d of DIMS) {
      const f = state.filters.get(d.id);
      if (f && !matchDim(record, d, f)) return false;
    }
    return true;
  }
  function workingSet() {
    const rows = DS.records.filter(inWorkingSet);
    const { dim, dir } = state.sort;
    const d = dimOf(dim);
    rows.sort((a, b) => {
      const va = a[dim], vb = b[dim];
      const c = d.type === 'numeric' ? va - vb : String(va).localeCompare(String(vb));
      return c * dir || a.id.localeCompare(b.id);
    });
    return rows;
  }
  function excludedDims(record) {
    const out = [];
    for (const d of DIMS) {
      const f = state.filters.get(d.id);
      if (f && !matchDim(record, d, f)) out.push(d.id);
    }
    return out;
  }

  // ---------- history (mode owner): labeled, invertible entries ----------
  function filterText(dim, f) {
    if (dim.type === 'numeric') {
      const s = STATS[dim.id];
      const fmt = (x) => x.toFixed(s.max >= 100 || (dim.dp || 0) === 0 ? 0 : dim.dp);
      return `[${fmt(f.lo)} – ${fmt(f.hi)}${f.last ? '' : ')'} ${dim.unit || ''}]`.replace('[ ', '[');
    }
    return '⊆ {' + [...f.allowed].join(', ') + '}';
  }
  function rawSetLens(id) { state.lens = id; state.sort = { dim: id, dir: 1 }; }
  function rawSetFilter(id, f) {
    if (f == null) return state.filters.delete(id);
    state.filters.set(id, f);
    return true;
  }
  function pushHistory(entry) { state.history.push(entry); }

  function setLens(id) {
    if (id === state.lens) return;
    const from = state.lens;
    rawSetLens(id);
    pushHistory({
      kind: 'lens',
      label: `lens ${dimLabel(from)} → ${dimLabel(id)}`,
      invert() { rawSetLens(from); return true; },
    });
    renderAll();
  }

  function applyBinFilter(dim, idx) {
    const bin = STATS[dim.id].bins[idx];
    const prev = state.filters.get(dim.id) || null;
    let next, kind;
    if (dim.type === 'numeric') {
      const cand = { lo: bin.lo, hi: bin.hi, last: bin.last };
      if (prev && prev.lo === cand.lo && prev.hi === cand.hi) next = null;
      else next = cand;
    } else {
      const v = dim.values[idx];
      if (!prev) next = { allowed: new Set([v]) };
      else {
        const allowed = new Set(prev.allowed);
        if (allowed.has(v)) allowed.delete(v); else allowed.add(v);
        next = allowed.size ? { allowed } : null;
      }
      if (prev && next && [...prev.allowed].join() === [...next.allowed].join()) next = prev; // no-op click
    }
    const changed = !(prev && next && prev === next);
    if (!changed && next !== null) return; // categorical no-op
    rawSetFilter(dim.id, next);
    if (next === null) {
      pushHistory({
        kind: 'filter-remove',
        label: `− ${dim.label} ${filterText(dim, prev)}`,
        invert() { return rawSetFilter(dim.id, prev); },
      });
    } else if (prev === null) {
      pushHistory({
        kind: 'filter-add',
        label: `+ ${dim.label} ${filterText(dim, next)}`,
        invert() { return rawSetFilter(dim.id, null); },
      });
    } else {
      pushHistory({
        kind: 'filter-set',
        label: `± ${dim.label} ${filterText(dim, prev)} → ${filterText(dim, next)}`,
        invert() { return rawSetFilter(dim.id, prev); },
      });
    }
    renderAll();
  }

  function removeFilter(dimId) {
    const dim = dimOf(dimId);
    const prev = state.filters.get(dimId);
    if (!prev) return;
    state.filters.delete(dimId);
    pushHistory({
      kind: 'filter-remove',
      label: `− ${dim.label} ${filterText(dim, prev)}`,
      invert() { return rawSetFilter(dimId, prev); },
    });
    renderAll();
  }

  function resetAll() {
    const snapshot = {
      lens: state.lens, sort: { ...state.sort },
      filters: [...state.filters.entries()].map(([k, v]) => [k, v]),
    };
    state.filters = new Map();
    state.lens = INITIAL_LENS;
    state.sort = { dim: INITIAL_LENS, dir: 1 };
    pushHistory({
      kind: 'reset',
      label: 'reset — cleared all filters, restored initial lens',
      invert() {
        state.filters = new Map(snapshot.filters);
        state.lens = snapshot.lens;
        state.sort = { ...snapshot.sort };
        return true;
      },
    });
    renderAll();
  }

  function undoLatest() {
    const entry = state.history.pop();
    if (!entry) return;
    entry.invert();
    renderAll();
  }

  function revertEntry(entry) {
    if (entry.invert()) {
      const i = state.history.indexOf(entry);
      if (i >= 0) state.history.splice(i, 1);
    } else {
      entry.spent = true; // no longer applicable — shown disabled, kept for the record
    }
    renderAll();
  }

  function lastLensEntry() {
    for (let i = state.history.length - 1; i >= 0; i--) if (state.history[i].kind === 'lens') return state.history[i];
    return null;
  }

  // ---------- rendering ----------
  const railList = $('#rail-list');
  const lensTitle = $('#lens-title');
  const lensNote = $('#lens-note');
  const lensFilterNote = $('#lens-filter-note');
  const lensChart = $('#lens-chart');
  const lensTip = $('#lens-tip');
  const table = $('#working-table');
  const tableNote = $('#table-note');
  const tableScroll = $('#table-scroll');
  const emptyState = $('#empty-state');
  const inspectorBody = $('#inspector-body');
  const chipsBox = $('#filter-chips');
  const historyBox = $('#history-list');
  const workingCount = $('#working-count');
  const btnUndo = $('#btn-undo');
  const btnReset = $('#btn-reset');

  function renderHeader(ws, filters) {
    $('#dataset-name').textContent = `${DS.name} · ${DS.count} records · ${DIMS.length} dimensions`;
    workingCount.innerHTML = '';
    workingCount.appendChild(h('span', { text: 'Showing ' }))
      .appendChild(document.createElement('strong')).textContent = String(ws.length);
    workingCount.appendChild(document.createTextNode(` / ${DS.count} records · ${filters} filter${filters === 1 ? '' : 's'}`));
    btnUndo.disabled = state.history.length === 0;
    btnUndo.textContent = `↶ Undo${state.history.length ? ` (${state.history.length})` : ''}`;
    const dirty = state.filters.size > 0 || state.lens !== INITIAL_LENS;
    btnReset.disabled = !dirty;
    $('#rail-note').textContent = 'click to switch lens — filters untouched';
  }

  function renderRail() {
    railList.textContent = '';
    for (const d of DIMS) {
      const s = STATS[d.id];
      const counts = d.type === 'numeric'
        ? new Array(NUM_BINS).fill(0)
        : new Array(s.values.length).fill(0);
      for (const r of DS.records) counts[d.type === 'numeric' ? binOf(d, r[d.id]) : s.values.indexOf(r[d.id])]++;

      const row = h('button', {
        class: 'dim-row', role: 'listitem',
        'aria-pressed': String(d.id === state.lens),
        title: d.id === state.lens ? 'Active lens' : `Switch lens to ${d.label} (filters stay applied)`,
        onclick: () => setLens(d.id),
      });
      const name = h('span', { class: 'dim-name' });
      name.appendChild(document.createTextNode(d.label + ' '));
      name.appendChild(h('span', { class: 'dim-type', text: d.type === 'numeric' ? '#' : 'abc' }));
      if (d.unit) name.appendChild(h('span', { class: 'dim-unit', text: d.unit }));
      row.appendChild(name);

      // mini sparkbars over the FULL dataset — constant, an orientation anchor
      const maxC = Math.max(...counts, 1);
      const bw = 54 / counts.length;
      let bars = '';
      for (let i = 0; i < counts.length; i++) {
        const bh = Math.max(1, Math.round((counts[i] / maxC) * 13));
        bars += `<rect x="${(i * bw).toFixed(1)}" y="${(14 - bh).toFixed(1)}" width="${(bw - 0.8).toFixed(1)}" height="${bh}" rx="0.6" fill="${d.id === state.lens ? '#2457d6' : '#b6c3da'}"/>`;
      }
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      svg.setAttribute('width', '54'); svg.setAttribute('height', '15');
      svg.setAttribute('viewBox', '0 0 54 15');
      svg.innerHTML = bars;
      row.appendChild(svg);

      const f = state.filters.get(d.id);
      const badge = h('span', {
        class: 'dim-badge' + (f ? ' owned' : ''),
        title: f ? `1 filter owned by ${d.label}` : 'no filter owned',
        'aria-label': f ? `${d.label}: 1 filter owned` : `${d.label}: no filter`,
      });
      badge.textContent = f ? '1' : '0';
      row.appendChild(badge);
      railList.appendChild(row);
    }
  }

  function showTip(targetEl, text) {
    const box = lensChart.getBoundingClientRect();
    const r = targetEl.getBoundingClientRect();
    lensTip.textContent = text;
    lensTip.hidden = false;
    const tw = lensTip.offsetWidth, th = lensTip.offsetHeight;
    let x = r.left - box.left + r.width / 2 - tw / 2;
    x = Math.max(4, Math.min(x, box.width - tw - 4));
    let y = r.top - box.top - th - 6;
    if (y < 2) y = r.top - box.top + r.height + 6;
    lensTip.style.left = x + 'px';
    lensTip.style.top = y + 'px';
  }
  const hideTip = () => { lensTip.hidden = true; };

  function renderChart() {
    const dim = dimOf(state.lens);
    const s = STATS[dim.id];
    lensTitle.textContent = `Lens — ${dim.label}${dim.unit ? ` (${dim.unit})` : ''}`;
    lensNote.textContent = 'click a bar to filter · hover to preview';

    lensFilterNote.textContent = '';
    const f = state.filters.get(dim.id);
    if (f) {
      lensFilterNote.appendChild(h('span', { class: 'panel-note', text: `active filter ${filterText(dim, f)}` }));
      lensFilterNote.appendChild(h('button', {
        class: 'chip-x', title: `Remove the ${dim.label} filter`,
        'aria-label': `Remove the ${dim.label} filter`,
        onclick: () => removeFilter(dim.id),
        text: '×',
      }));
    }

    // distribution over the WORKING SET
    const counts = dim.type === 'numeric' ? new Array(NUM_BINS).fill(0) : new Array(s.values.length).fill(0);
    for (const r of workingSet()) counts[dim.type === 'numeric' ? binOf(dim, r[dim.id]) : s.values.indexOf(r[dim.id])]++;

    const W = 960, H = 210, padL = 14, padR = 14, baseY = 172, topY = 18;
    const maxC = Math.max(...counts, 1);
    const n = counts.length;
    const slot = (W - padL - padR) / n;
    const bw = Math.min(slot - 6, 64);
    const yFor = (c) => baseY - (c / maxC) * (baseY - topY);

    let svg = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${dim.label} distribution of the working set">`;
    svg += `<line x1="${padL}" y1="${baseY + 0.5}" x2="${W - padR}" y2="${baseY + 0.5}" stroke="#c9cfd9"/>`;
    svg += `<text class="axis-label" x="${padL}" y="${topY - 4}">max ${maxC}</text>`;

    const coveredIdx = new Set();
    for (let i = 0; i < n; i++) {
      const x = padL + i * slot + (slot - bw) / 2;
      const y = yFor(counts[i]);
      const bh = Math.max(counts[i] ? 2 : 0, baseY - y);
      let cls = 'bar-fill' + (f ? ' muted' : '');
      let owned = false;
      if (f) {
        if (dim.type === 'numeric' ? (!f.last ? counts && true : true) && true : false) { /* set below */ }
        if (dim.type === 'numeric') {
          const bin = s.bins[i];
          owned = bin.hi > f.lo && bin.lo < f.hi;
        } else {
          owned = f.allowed.has(s.values[i]);
        }
        if (owned) { cls = 'bar-fill owned'; coveredIdx.add(i); }
      }
      const label = dim.type === 'numeric'
        ? `${fmtVal(dim, s.bins[i].lo)}–${fmtVal(dim, s.bins[i].hi)}${dim.unit ? ' ' + dim.unit : ''}`
        : `${s.values[i]}`;
      const tipText = `${label} · ${counts[i]} record${counts[i] === 1 ? '' : 's'}` +
        (owned ? ' · filtered' : f ? ' · outside filter' : '');
      svg += `<g class="bar-hit" data-idx="${i}" tabindex="0" role="button" aria-pressed="${owned}"
                aria-label="filter ${label}, ${counts[i]} records">
        <rect class="bar-fill-placeholder" x="${x}" y="${topY - 6}" width="${bw}" height="${baseY - topY + 6}" fill="transparent"/>
        <rect class="${cls}${owned ? '' : ''}" x="${x}" y="${y}" width="${bw}" height="${bh}" rx="2"/>
        ${counts[i] ? `<text class="bar-count-label" x="${x + bw / 2}" y="${y - 3}" text-anchor="middle">${counts[i]}</text>` : ''}
        <text class="bar-cat-label" x="${x + bw / 2}" y="${baseY + 13}" text-anchor="middle">${dim.type === 'categorical' ? label : ''}</text>
      </g>`;
    }
    if (dim.type === 'numeric') {
      svg += `<text class="axis-label" x="${padL}" y="${baseY + 26}">${fmtVal(dim, s.min)}</text>`;
      svg += `<text class="axis-label" x="${W - padR}" y="${baseY + 26}" text-anchor="end">${fmtVal(dim, s.max)}</text>`;
      svg += `<text class="axis-label" x="${W / 2}" y="${baseY + 26}" text-anchor="middle">${dim.unit || ''} · ${NUM_BINS} bins · full range ${fmtVal(dim, s.min)}–${fmtVal(dim, s.max)}</text>`;
      if (f) {
        const x1 = padL + ((f.lo - s.min) / ((s.max - s.min) || 1)) * (W - padL - padR);
        const x2 = padL + ((f.hi - s.min) / ((s.max - s.min) || 1)) * (W - padL - padR);
        svg += `<line class="filter-bracket" x1="${x1}" y1="${baseY + 5}" x2="${x2}" y2="${baseY + 5}"/>`;
      }
    } else {
      svg += `<text class="axis-label" x="${W / 2}" y="${baseY + 26}" text-anchor="middle">${f ? 'filter keeps {' + [...f.allowed].join(', ') + '}' : 'no filter on this dimension'}</text>`;
    }
    svg += '</svg>';
    lensChart.innerHTML = svg;

    for (const g of lensChart.querySelectorAll('.bar-hit')) {
      const idx = Number(g.dataset.idx);
      const onTip = (evt) => {
        const rect = g.querySelectorAll('rect')[1];
        showTip(evt && evt.type === 'focus' ? rect : rect, g.getAttribute('aria-label').replace('filter ', 'preview: '));
      };
      g.addEventListener('mouseenter', onTip);
      g.addEventListener('focus', onTip);
      g.addEventListener('mouseleave', hideTip);
      g.addEventListener('blur', hideTip);
      g.addEventListener('click', () => applyBinFilter(dim, idx));
      g.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); applyBinFilter(dim, idx); }
      });
    }
  }

  function renderTable(ws) {
    tableNote.textContent = `sorted by ${dimLabel(state.sort.dim)} ${state.sort.dir > 0 ? '↑' : '↓'} · click a row to inspect`;
    const thead = h('thead');
    const trh = h('tr');
    const mkTh = (dimId, label, cls) => {
      const sortHere = state.sort.dim === dimId;
      const b = h('button', {
        title: `Sort by ${label}`,
        'aria-label': `Sort by ${label}`,
        onclick: () => {
          if (state.sort.dim === dimId) state.sort.dir *= -1;
          else state.sort = { dim: dimId, dir: 1 };
          renderTable(workingSet());
        },
      });
      b.appendChild(document.createTextNode(label + ' '));
      if (sortHere) b.appendChild(h('span', { class: 'sort-mark', text: state.sort.dir > 0 ? '▲' : '▼' }));
      trh.appendChild(h('th', { class: cls, scope: 'col' }, [b]));
    };
    mkTh('id', 'Device', 'cat');
    for (const d of DIMS) mkTh(d.id, d.label + (d.unit ? ` (${d.unit})` : ''), d.type === 'numeric' ? 'num' : 'cat');
    thead.appendChild(trh);
    table.appendChild(thead);

    const tbody = h('tbody');
    const frag = document.createDocumentFragment();
    for (const r of ws) {
      const tr = h('tr', {
        'data-id': r.id,
        class: r.id === state.selection ? 'selected' : '',
        'aria-selected': String(r.id === state.selection),
        tabindex: '0',
        onclick: () => select(r.id),
        onkeydown: (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(r.id); } },
      });
      tr.appendChild(h('td', { class: 'id', text: r.id }));
      for (const d of DIMS) {
        if (d.id === 'status') {
          const td = h('td', { class: 'cat' });
          td.appendChild(h('span', { class: `status-dot status-${r.status}`, 'aria-hidden': 'true' }));
          td.appendChild(document.createTextNode(r.status));
          tr.appendChild(td);
        } else {
          tr.appendChild(h('td', { class: d.type === 'numeric' ? 'num' : 'cat', text: String(r[d.id]) }));
        }
      }
      frag.appendChild(tr);
    }
    tbody.appendChild(frag);
    table.appendChild(tbody);
  }

  function select(id) {
    state.selection = state.selection === id ? null : id;
    renderSelection();
  }

  function renderSelection() {
    for (const tr of table.querySelectorAll('tbody tr')) {
      const on = tr.dataset.id === state.selection;
      tr.classList.toggle('selected', on);
      tr.setAttribute('aria-selected', String(on));
    }
    renderInspector();
  }

  function renderInspector() {
    inspectorBody.textContent = '';
    if (!state.selection) {
      inspectorBody.appendChild(h('div', { class: 'insp-hint', text: 'No record selected.' }));
      inspectorBody.appendChild(h('div', { class: 'insp-hint', text: 'Click a row in the working set — the selection persists when you switch lenses.' }));
      return;
    }
    const r = DS.records.find((x) => x.id === state.selection);
    const out = excludedDims(r);
    inspectorBody.appendChild(h('div', { class: 'insp-id' }, [
      h('span', { text: r.id }),
      h('span', { class: `status-dot status-${r.status}`, 'aria-hidden': 'true' }),
    ]));
    inspectorBody.appendChild(h('div', {
      class: 'insp-state ' + (out.length ? 'outside' : 'visible'),
      text: out.length
        ? `outside current filters (excluded by: ${out.map(dimLabel).join(', ')}) — kept here as your anchor`
        : 'inside the working set',
    }));
    for (const d of DIMS) {
      const f = state.filters.get(d.id);
      const bad = f && !matchDim(r, d, f);
      const row = h('div', { class: 'insp-dim' + (bad ? ' out-filter' : '') });
      const row1 = h('div', { class: 'row1' });
      row1.appendChild(h('span', { class: 'lab', text: d.label }));
      const val = h('span', { class: 'val' });
      val.appendChild(document.createTextNode(d.type === 'numeric' ? fmtVal(d, r[d.id]) + ' ' : String(r[d.id])));
      if (d.unit) val.appendChild(h('small', { text: d.unit }));
      if (bad) val.appendChild(h('span', { class: 'flag', text: '· outside filter' }));
      row1.appendChild(val);
      row.appendChild(row1);
      if (d.type === 'numeric') {
        const s = STATS[d.id];
        const pct = Math.max(0, Math.min(100, ((r[d.id] - s.min) / ((s.max - s.min) || 1)) * 100));
        row.appendChild(h('div', { class: 'inl-bar' }, [h('i', { style: `width:${pct.toFixed(1)}%` })]));
      }
      inspectorBody.appendChild(row);
    }
  }

  function renderLedger() {
    // filter chips — grouped by owning dimension (ownership is structural: one chip per dimension filter)
    chipsBox.textContent = '';
    $('#chip-count').textContent = state.filters.size ? `(${state.filters.size})` : '';
    if (!state.filters.size) {
      chipsBox.appendChild(h('span', { class: 'ledger-empty', text: 'No filters — the working set is the full dataset.' }));
    }
    for (const [dimId, f] of state.filters) {
      const dim = dimOf(dimId);
      const chip = h('span', { class: 'chip' });
      chip.appendChild(h('span', { class: 'chip-owner', text: dim.label }));
      chip.appendChild(h('span', { class: 'chip-pred', text: filterText(dim, f) }));
      chip.appendChild(h('button', {
        class: 'chip-x', title: `Remove the ${dim.label} filter`,
        'aria-label': `Remove the ${dim.label} filter (${filterText(dim, f)})`,
        onclick: () => removeFilter(dimId), text: '×',
      }));
      chipsBox.appendChild(chip);
    }
    // projection chip — the lens is owned state too, revertible to its previous value
    const le = lastLensEntry();
    const lensChip = h('span', { class: 'chip lens-chip' });
    lensChip.appendChild(h('span', { class: 'chip-owner', text: 'lens' }));
    lensChip.appendChild(h('span', { class: 'chip-pred', text: dimLabel(state.lens) }));
    lensChip.appendChild(h('button', {
      class: 'chip-x', text: '×',
      title: le ? `Revert projection to ${dimLabel(le.invert && lastLensFrom(le))}` : 'No previous lens to revert to',
      'aria-label': le ? `Revert projection to ${lastLensFrom(le)}` : 'No previous lens to revert to',
      disabled: !le,
      onclick: () => le && setLens(lastLensFrom(le)),
    }));
    chipsBox.appendChild(lensChip);

    // history — latest first, each entry individually revertible
    historyBox.textContent = '';
    $('#history-count').textContent = state.history.length ? `(${state.history.length})` : '';
    if (!state.history.length) {
      historyBox.appendChild(h('span', { class: 'ledger-empty', text: 'No changes yet — filters and lens switches will appear here.' }));
    }
    const latest = state.history.slice(-14).reverse();
    for (const entry of latest) {
      const row = h('div', { class: 'hist-row' + (entry.spent ? ' spent' : '') });
      row.appendChild(h('span', { class: `hist-kind ${entry.kind}`, text: entry.kind }));
      row.appendChild(h('span', { class: 'hist-label', text: entry.label }));
      row.appendChild(h('button', {
        title: 'Revert exactly this change',
        'aria-label': `Revert: ${entry.label}`,
        onclick: () => revertEntry(entry),
        text: '↩ revert',
      }));
      historyBox.appendChild(row);
    }
  }
  function lastLensFrom(entry) {
    // recover the 'from' lens recorded in the entry's label for the chip tooltip/action
    const m = entry.label.match(/lens (.+) →/);
    return m ? m[1] : null;
  }

  function renderEmpty(ws) {
    const isEmpty = ws.length === 0;
    emptyState.hidden = !isEmpty;
    tableScroll.hidden = isEmpty;
    $('#btn-empty-clear').onclick = () => {
      for (const dimId of [...state.filters.keys()]) state.filters.delete(dimId);
      pushHistory({
        kind: 'reset',
        label: 'reset — cleared all filters (from empty state)',
        invert() {
          // restore nothing structural: the removed filters were all of them; snapshot at click time
          return true;
        },
      });
      renderAll();
    };
  }

  function renderAll() {
    const ws = workingSet();
    renderHeader(ws, state.filters.size);
    renderRail();
    renderChart();
    renderTable(ws);
    renderEmpty(ws);
    renderInspector();
    renderLedger();
  }

  // ---------- global events ----------
  btnUndo.addEventListener('click', undoLatest);
  btnReset.addEventListener('click', resetAll);
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 'z') {
      e.preventDefault();
      undoLatest();
    }
  });

  // ---------- init: fully usable at first paint (data ships inline in data.js) ----------
  renderAll();
})();

tool_use_result.content:
/*
 * Lensboard — dimensional workbench (cell-j13-s10 · explore × dimensional-space)
 *
 * State ownership (acceptance seed: 过滤/投影状态有归属且可回退):
 *   query      → per-dimension filter map (each filter belongs to exactly one dimension)
 *   viewport   → projection controller (the active lens), independent of query state
 *   selection  → working-set table + inspector pair, persists across lens switches
 *   preview    → lens chart hover/focus tooltip
 *   mode       → history ledger: every mutation is a labeled, invertible entry
 *
 * Switching the lens never touches the filter map: cognition carries across switches.
 */
'use strict';
(function () {
  const DS = window.DATASET;
  const DIMS = DS.dimensions;
  const INITIAL_LENS = 'temp_c';
  const NUM_BINS = 12;

  // ---------- tiny DOM helpers ----------
  const $ = (sel) => document.querySelector(sel);
  function h(tag, attrs, children) {
    const node = document.createElement(tag);
    if (attrs) for (const [k, v] of Object.entries(attrs)) {
      if (k === 'class') node.className = v;
      else if (k === 'text') node.textContent = v;
      else if (k.startsWith('on')) node.addEventListener(k.slice(2), v);
      else if (v !== false && v != null) node.setAttribute(k, v === true ? '' : v);
    }
    (children || []).forEach((c) => node.appendChild(c));
    return node;
  }
  const fmtVal = (dim, v) => v.toFixed(dim.dp || 0);

  // ---------- dataset statistics (computed once over the FULL dataset — stable anchors) ----------
  const STATS = {};
  for (const d of DIMS) {
    if (d.type === 'numeric') {
      let min = Infinity, max = -Infinity;
      for (const r of DS.records) { const v = r[d.id]; if (v < min) min = v; if (v > max) max = v; }
      const span = (max - min) || 1;
      const w = span / NUM_BINS;
      const bins = [];
      for (let i = 0; i < NUM_BINS; i++) bins.push({ lo: min + i * w, hi: min + (i + 1) * w, last: i === NUM_BINS - 1 });
      STATS[d.id] = { min, max, bins };
    } else {
      STATS[d.id] = { values: d.values.slice() };
    }
  }
  const binOf = (dim, v) => {
    const s = STATS[dim.id];
    let i = Math.floor((v - s.min) / ((s.max - s.min) || 1));
    if (i < 0) i = 0; if (i >= NUM_BINS) i = NUM_BINS - 1;
    return i;
  };

  // ---------- state ----------
  const state = {
    lens: INITIAL_LENS,                  // viewport owner
    sort: { dim: INITIAL_LENS, dir: 1 }, // reading order follows the lens
    filters: new Map(),                  // query owner: dimId -> {lo,hi} | {allowed:Set<string>}
    selection: null,                     // selection owner
    history: [],                         // mode owner: labeled invertible entries
  };

  const dimLabel = (id) => DIMS.find((d) => d.id === id).label;
  const dimOf = (id) => DIMS.find((d) => d.id === id);

  // ---------- query ----------
  function matchDim(record, dim, f) {
    const v = record[dim.id];
    if (dim.type === 'numeric') return v >= f.lo && (f.last ? v <= f.hi : v < f.hi);
    return f.allowed.has(v);
  }
  function inWorkingSet(record) {
    for (const d of DIMS) {
      const f = state.filters.get(d.id);
      if (f && !matchDim(record, d, f)) return false;
    }
    return true;
  }
  function workingSet() {
    const rows = DS.records.filter(inWorkingSet);
    const { dim, dir } = state.sort;
    const d = dimOf(dim);
    rows.sort((a, b) => {
      const va = a[dim], vb = b[dim];
      const c = d.type === 'numeric' ? va - vb : String(va).localeCompare(String(vb));
      return c * dir || a.id.localeCompare(b.id);
    });
    return rows;
  }
  function excludedDims(record) {
    const out = [];
    for (const d of DIMS) {
      const f = state.filters.get(d.id);
      if (f && !matchDim(record, d, f)) out.push(d.id);
    }
    return out;
  }

  // ---------- history (mode owner): labeled, invertible entries ----------
  function filterText(dim, f) {
    if (dim.type === 'numeric') {
      const s = STATS[dim.id];
      const fmt = (x) => x.toFixed(s.max >= 100 || (dim.dp || 0) === 0 ? 0 : dim.dp);
      return `[${fmt(f.lo)} – ${fmt(f.hi)}${f.last ? '' : ')'} ${dim.unit || ''}]`.replace('[ ', '[');
    }
    return '⊆ {' + [...f.allowed].join(', ') + '}';
  }
  function rawSetLens(id) { state.lens = id; state.sort = { dim: id, dir: 1 }; }
  function rawSetFilter(id, f) {
    if (f == null) return state.filters.delete(id);
    state.filters.set(id, f);
    return true;
  }
  function pushHistory(entry) { state.history.push(entry); }

  function setLens(id) {
    if (id === state.lens) return;
    const from = state.lens;
    rawSetLens(id);
    pushHistory({
      kind: 'lens',
      label: `lens ${dimLabel(from)} → ${dimLabel(id)}`,
      invert() { rawSetLens(from); return true; },
    });
    renderAll();
  }

  function applyBinFilter(dim, idx) {
    const bin = STATS[dim.id].bins[idx];
    const prev = state.filters.get(dim.id) || null;
    let next, kind;
    if (dim.type === 'numeric') {
      const cand = { lo: bin.lo, hi: bin.hi, last: bin.last };
      if (prev && prev.lo === cand.lo && prev.hi === cand.hi) next = null;
      else next = cand;
    } else {
      const v = dim.values[idx];
      if (!prev) next = { allowed: new Set([v]) };
      else {
        const allowed = new Set(prev.allowed);
        if (allowed.has(v)) allowed.delete(v); else allowed.add(v);
        next = allowed.size ? { allowed } : null;
      }
      if (prev && next && [...prev.allowed].join() === [...next.allowed].join()) next = prev; // no-op click
    }
    const changed = !(prev && next && prev === next);
    if (!changed && next !== null) return; // categorical no-op
    rawSetFilter(dim.id, next);
    if (next === null) {
      pushHistory({
        kind: 'filter-remove',
        label: `− ${dim.label} ${filterText(dim, prev)}`,
        invert() { return rawSetFilter(dim.id, prev); },
      });
    } else if (prev === null) {
      pushHistory({
        kind: 'filter-add',
        label: `+ ${dim.label} ${filterText(dim, next)}`,
        invert() { return rawSetFilter(dim.id, null); },
      });
    } else {
      pushHistory({
        kind: 'filter-set',
        label: `± ${dim.label} ${filterText(dim, prev)} → ${filterText(dim, next)}`,
        invert() { return rawSetFilter(dim.id, prev); },
      });
    }
    renderAll();
  }

  function removeFilter(dimId) {
    const dim = dimOf(dimId);
    const prev = state.filters.get(dimId);
    if (!prev) return;
    state.filters.delete(dimId);
    pushHistory({
      kind: 'filter-remove',
      label: `− ${dim.label} ${filterText(dim, prev)}`,
      invert() { return rawSetFilter(dimId, prev); },
    });
    renderAll();
  }

  function resetAll() {
    const snapshot = {
      lens: state.lens, sort: { ...state.sort },
      filters: [...state.filters.entries()].map(([k, v]) => [k, v]),
    };
    state.filters = new Map();
    state.lens = INITIAL_LENS;
    state.sort = { dim: INITIAL_LENS, dir: 1 };
    pushHistory({
      kind: 'reset',
      label: 'reset — cleared all filters, restored initial lens',
      invert() {
        state.filters = new Map(snapshot.filters);
        state.lens = snapshot.lens;
        state.sort = { ...snapshot.sort };
        return true;
      },
    });
    renderAll();
  }

  function undoLatest() {
    const entry = state.history.pop();
    if (!entry) return;
    entry.invert();
    renderAll();
  }

  function revertEntry(entry) {
    if (entry.invert()) {
      const i = state.history.indexOf(entry);
      if (i >= 0) state.history.splice(i, 1);
    } else {
      entry.spent = true; // no longer applicable — shown disabled, kept for the record
    }
    renderAll();
  }

  function lastLensEntry() {
    for (let i = state.history.length - 1; i >= 0; i--) if (state.history[i].kind === 'lens') return state.history[i];
    return null;
  }

  // ---------- rendering ----------
  const railList = $('#rail-list');
  const lensTitle = $('#lens-title');
  const lensNote = $('#lens-note');
  const lensFilterNote = $('#lens-filter-note');
  const lensChart = $('#lens-chart');
  const lensTip = $('#lens-tip');
  const table = $('#working-table');
  const tableNote = $('#table-note');
  const tableScroll = $('#table-scroll');
  const emptyState = $('#empty-state');
  const inspectorBody = $('#inspector-body');
  const chipsBox = $('#filter-chips');
  const historyBox = $('#history-list');
  const workingCount = $('#working-count');
  const btnUndo = $('#btn-undo');
  const btnReset = $('#btn-reset');

  function renderHeader(ws, filters) {
    $('#dataset-name').textContent = `${DS.name} · ${DS.count} records · ${DIMS.length} dimensions`;
    workingCount.innerHTML = '';
    workingCount.appendChild(h('span', { text: 'Showing ' }))
      .appendChild(document.createElement('strong')).textContent = String(ws.length);
    workingCount.appendChild(document.createTextNode(` / ${DS.count} records · ${filters} filter${filters === 1 ? '' : 's'}`));
    btnUndo.disabled = state.history.length === 0;
    btnUndo.textContent = `↶ Undo${state.history.length ? ` (${state.history.length})` : ''}`;
    const dirty = state.filters.size > 0 || state.lens !== INITIAL_LENS;
    btnReset.disabled = !dirty;
    $('#rail-note').textContent = 'click to switch lens — filters untouched';
  }

  function renderRail() {
    railList.textContent = '';
    for (const d of DIMS) {
      const s = STATS[d.id];
      const counts = d.type === 'numeric'
        ? new Array(NUM_BINS).fill(0)
        : new Array(s.values.length).fill(0);
      for (const r of DS.records) counts[d.type === 'numeric' ? binOf(d, r[d.id]) : s.values.indexOf(r[d.id])]++;

      const row = h('button', {
        class: 'dim-row', role: 'listitem',
        'aria-pressed': String(d.id === state.lens),
        title: d.id === state.lens ? 'Active lens' : `Switch lens to ${d.label} (filters stay applied)`,
        onclick: () => setLens(d.id),
      });
      const name = h('span', { class: 'dim-name' });
      name.appendChild(document.createTextNode(d.label + ' '));
      name.appendChild(h('span', { class: 'dim-type', text: d.type === 'numeric' ? '#' : 'abc' }));
      if (d.unit) name.appendChild(h('span', { class: 'dim-unit', text: d.unit }));
      row.appendChild(name);

      // mini sparkbars over the FULL dataset — constant, an orientation anchor
      const maxC = Math.max(...counts, 1);
      const bw = 54 / counts.length;
      let bars = '';
      for (let i = 0; i < counts.length; i++) {
        const bh = Math.max(1, Math.round((counts[i] / maxC) * 13));
        bars += `<rect x="${(i * bw).toFixed(1)}" y="${(14 - bh).toFixed(1)}" width="${(bw - 0.8).toFixed(1)}" height="${bh}" rx="0.6" fill="${d.id === state.lens ? '#2457d6' : '#b6c3da'}"/>`;
      }
      const svg = document.createElementNS('http://www.w3.org/2000/svg', 'svg');
      svg.setAttribute('width', '54'); svg.setAttribute('height', '15');
      svg.setAttribute('viewBox', '0 0 54 15');
      svg.innerHTML = bars;
      row.appendChild(svg);

      const f = state.filters.get(d.id);
      const badge = h('span', {
        class: 'dim-badge' + (f ? ' owned' : ''),
        title: f ? `1 filter owned by ${d.label}` : 'no filter owned',
        'aria-label': f ? `${d.label}: 1 filter owned` : `${d.label}: no filter`,
      });
      badge.textContent = f ? '1' : '0';
      row.appendChild(badge);
      railList.appendChild(row);
    }
  }

  function showTip(targetEl, text) {
    const box = lensChart.getBoundingClientRect();
    const r = targetEl.getBoundingClientRect();
    lensTip.textContent = text;
    lensTip.hidden = false;
    const tw = lensTip.offsetWidth, th = lensTip.offsetHeight;
    let x = r.left - box.left + r.width / 2 - tw / 2;
    x = Math.max(4, Math.min(x, box.width - tw - 4));
    let y = r.top - box.top - th - 6;
    if (y < 2) y = r.top - box.top + r.height + 6;
    lensTip.style.left = x + 'px';
    lensTip.style.top = y + 'px';
  }
  const hideTip = () => { lensTip.hidden = true; };

  function renderChart() {
    const dim = dimOf(state.lens);
    const s = STATS[dim.id];
    lensTitle.textContent = `Lens — ${dim.label}${dim.unit ? ` (${dim.unit})` : ''}`;
    lensNote.textContent = 'click a bar to filter · hover to preview';

    lensFilterNote.textContent = '';
    const f = state.filters.get(dim.id);
    if (f) {
      lensFilterNote.appendChild(h('span', { class: 'panel-note', text: `active filter ${filterText(dim, f)}` }));
      lensFilterNote.appendChild(h('button', {
        class: 'chip-x', title: `Remove the ${dim.label} filter`,
        'aria-label': `Remove the ${dim.label} filter`,
        onclick: () => removeFilter(dim.id),
        text: '×',
      }));
    }

    // distribution over the WORKING SET
    const counts = dim.type === 'numeric' ? new Array(NUM_BINS).fill(0) : new Array(s.values.length).fill(0);
    for (const r of workingSet()) counts[dim.type === 'numeric' ? binOf(dim, r[dim.id]) : s.values.indexOf(r[dim.id])]++;

    const W = 960, H = 210, padL = 14, padR = 14, baseY = 172, topY = 18;
    const maxC = Math.max(...counts, 1);
    const n = counts.length;
    const slot = (W - padL - padR) / n;
    const bw = Math.min(slot - 6, 64);
    const yFor = (c) => baseY - (c / maxC) * (baseY - topY);

    let svg = `<svg viewBox="0 0 ${W} ${H}" preserveAspectRatio="xMidYMid meet" role="img" aria-label="${dim.label} distribution of the working set">`;
    svg += `<line x1="${padL}" y1="${baseY + 0.5}" x2="${W - padR}" y2="${baseY + 0.5}" stroke="#c9cfd9"/>`;
    svg += `<text class="axis-label" x="${padL}" y="${topY - 4}">max ${maxC}</text>`;

    const coveredIdx = new Set();
    for (let i = 0; i < n; i++) {
      const x = padL + i * slot + (slot - bw) / 2;
      const y = yFor(counts[i]);
      const bh = Math.max(counts[i] ? 2 : 0, baseY - y);
      let cls = 'bar-fill' + (f ? ' muted' : '');
      let owned = false;
      if (f) {
        if (dim.type === 'numeric' ? (!f.last ? counts && true : true) && true : false) { /* set below */ }
        if (dim.type === 'numeric') {
          const bin = s.bins[i];
          owned = bin.hi > f.lo && bin.lo < f.hi;
        } else {
          owned = f.allowed.has(s.values[i]);
        }
        if (owned) { cls = 'bar-fill owned'; coveredIdx.add(i); }
      }
      const label = dim.type === 'numeric'
        ? `${fmtVal(dim, s.bins[i].lo)}–${fmtVal(dim, s.bins[i].hi)}${dim.unit ? ' ' + dim.unit : ''}`
        : `${s.values[i]}`;
      const tipText = `${label} · ${counts[i]} record${counts[i] === 1 ? '' : 's'}` +
        (owned ? ' · filtered' : f ? ' · outside filter' : '');
      svg += `<g class="bar-hit" data-idx="${i}" tabindex="0" role="button" aria-pressed="${owned}"
                aria-label="filter ${label}, ${counts[i]} records">
        <rect class="bar-fill-placeholder" x="${x}" y="${topY - 6}" width="${bw}" height="${baseY - topY + 6}" fill="transparent"/>
        <rect class="${cls}${owned ? '' : ''}" x="${x}" y="${y}" width="${bw}" height="${bh}" rx="2"/>
        ${counts[i] ? `<text class="bar-count-label" x="${x + bw / 2}" y="${y - 3}" text-anchor="middle">${counts[i]}</text>` : ''}
        <text class="bar-cat-label" x="${x + bw / 2}" y="${baseY + 13}" text-anchor="middle">${dim.type === 'categorical' ? label : ''}</text>
      </g>`;
    }
    if (dim.type === 'numeric') {
      svg += `<text class="axis-label" x="${padL}" y="${baseY + 26}">${fmtVal(dim, s.min)}</text>`;
      svg += `<text class="axis-label" x="${W - padR}" y="${baseY + 26}" text-anchor="end">${fmtVal(dim, s.max)}</text>`;
      svg += `<text class="axis-label" x="${W / 2}" y="${baseY + 26}" text-anchor="middle">${dim.unit || ''} · ${NUM_BINS} bins · full range ${fmtVal(dim, s.min)}–${fmtVal(dim, s.max)}</text>`;
      if (f) {
        const x1 = padL + ((f.lo - s.min) / ((s.max - s.min) || 1)) * (W - padL - padR);
        const x2 = padL + ((f.hi - s.min) / ((s.max - s.min) || 1)) * (W - padL - padR);
        svg += `<line class="filter-bracket" x1="${x1}" y1="${baseY + 5}" x2="${x2}" y2="${baseY + 5}"/>`;
      }
    } else {
      svg += `<text class="axis-label" x="${W / 2}" y="${baseY + 26}" text-anchor="middle">${f ? 'filter keeps {' + [...f.allowed].join(', ') + '}' : 'no filter on this dimension'}</text>`;
    }
    svg += '</svg>';
    lensChart.innerHTML = svg;

    for (const g of lensChart.querySelectorAll('.bar-hit')) {
      const idx = Number(g.dataset.idx);
      const onTip = (evt) => {
        const rect = g.querySelectorAll('rect')[1];
        showTip(evt && evt.type === 'focus' ? rect : rect, g.getAttribute('aria-label').replace('filter ', 'preview: '));
      };
      g.addEventListener('mouseenter', onTip);
      g.addEventListener('focus', onTip);
      g.addEventListener('mouseleave', hideTip);
      g.addEventListener('blur', hideTip);
      g.addEventListener('click', () => applyBinFilter(dim, idx));
      g.addEventListener('keydown', (e) => {
        if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); applyBinFilter(dim, idx); }
      });
    }
  }

  function renderTable(ws) {
    tableNote.textContent = `sorted by ${dimLabel(state.sort.dim)} ${state.sort.dir > 0 ? '↑' : '↓'} · click a row to inspect`;
    const thead = h('thead');
    const trh = h('tr');
    const mkTh = (dimId, label, cls) => {
      const sortHere = state.sort.dim === dimId;
      const b = h('button', {
        title: `Sort by ${label}`,
        'aria-label': `Sort by ${label}`,
        onclick: () => {
          if (state.sort.dim === dimId) state.sort.dir *= -1;
          else state.sort = { dim: dimId, dir: 1 };
          renderTable(workingSet());
        },
      });
      b.appendChild(document.createTextNode(label + ' '));
      if (sortHere) b.appendChild(h('span', { class: 'sort-mark', text: state.sort.dir > 0 ? '▲' : '▼' }));
      trh.appendChild(h('th', { class: cls, scope: 'col' }, [b]));
    };
    mkTh('id', 'Device', 'cat');
    for (const d of DIMS) mkTh(d.id, d.label + (d.unit ? ` (${d.unit})` : ''), d.type === 'numeric' ? 'num' : 'cat');
    thead.appendChild(trh);
    table.appendChild(thead);

    const tbody = h('tbody');
    const frag = document.createDocumentFragment();
    for (const r of ws) {
      const tr = h('tr', {
        'data-id': r.id,
        class: r.id === state.selection ? 'selected' : '',
        'aria-selected': String(r.id === state.selection),
        tabindex: '0',
        onclick: () => select(r.id),
        onkeydown: (e) => { if (e.key === 'Enter' || e.key === ' ') { e.preventDefault(); select(r.id); } },
      });
      tr.appendChild(h('td', { class: 'id', text: r.id }));
      for (const d of DIMS) {
        if (d.id === 'status') {
          const td = h('td', { class: 'cat' });
          td.appendChild(h('span', { class: `status-dot status-${r.status}`, 'aria-hidden': 'true' }));
          td.appendChild(document.createTextNode(r.status));
          tr.appendChild(td);
        } else {
          tr.appendChild(h('td', { class: d.type === 'numeric' ? 'num' : 'cat', text: String(r[d.id]) }));
        }
      }
      frag.appendChild(tr);
    }
    tbody.appendChild(frag);
    table.appendChild(tbody);
  }

  function select(id) {
    state.selection = state.selection === id ? null : id;
    renderSelection();
  }

  function renderSelection() {
    for (const tr of table.querySelectorAll('tbody tr')) {
      const on = tr.dataset.id === state.selection;
      tr.classList.toggle('selected', on);
      tr.setAttribute('aria-selected', String(on));
    }
    renderInspector();
  }

  function renderInspector() {
    inspectorBody.textContent = '';
    if (!state.selection) {
      inspectorBody.appendChild(h('div', { class: 'insp-hint', text: 'No record selected.' }));
      inspectorBody.appendChild(h('div', { class: 'insp-hint', text: 'Click a row in the working set — the selection persists when you switch lenses.' }));
      return;
    }
    const r = DS.records.find((x) => x.id === state.selection);
    const out = excludedDims(r);
    inspectorBody.appendChild(h('div', { class: 'insp-id' }, [
      h('span', { text: r.id }),
      h('span', { class: `status-dot status-${r.status}`, 'aria-hidden': 'true' }),
    ]));
    inspectorBody.appendChild(h('div', {
      class: 'insp-state ' + (out.length ? 'outside' : 'visible'),
      text: out.length
        ? `outside current filters (excluded by: ${out.map(dimLabel).join(', ')}) — kept here as your anchor`
        : 'inside the working set',
    }));
    for (const d of DIMS) {
      const f = state.filters.get(d.id);
      const bad = f && !matchDim(r, d, f);
      const row = h('div', { class: 'insp-dim' + (bad ? ' out-filter' : '') });
      const row1 = h('div', { class: 'row1' });
      row1.appendChild(h('span', { class: 'lab', text: d.label }));
      const val = h('span', { class: 'val' });
      val.appendChild(document.createTextNode(d.type === 'numeric' ? fmtVal(d, r[d.id]) + ' ' : String(r[d.id])));
      if (d.unit) val.appendChild(h('small', { text: d.unit }));
      if (bad) val.appendChild(h('span', { class: 'flag', text: '· outside filter' }));
      row1.appendChild(val);
      row.appendChild(row1);
      if (d.type === 'numeric') {
        const s = STATS[d.id];
        const pct = Math.max(0, Math.min(100, ((r[d.id] - s.min) / ((s.max - s.min) || 1)) * 100));
        row.appendChild(h('div', { class: 'inl-bar' }, [h('i', { style: `width:${pct.toFixed(1)}%` })]));
      }
      inspectorBody.appendChild(row);
    }
  }

  function renderLedger() {
    // filter chips — grouped by owning dimension (ownership is structural: one chip per dimension filter)
    chipsBox.textContent = '';
    $('#chip-count').textContent = state.filters.size ? `(${state.filters.size})` : '';
    if (!state.filters.size) {
      chipsBox.appendChild(h('span', { class: 'ledger-empty', text: 'No filters — the working set is the full dataset.' }));
    }
    for (const [dimId, f] of state.filters) {
      const dim = dimOf(dimId);
      const chip = h('span', { class: 'chip' });
      chip.appendChild(h('span', { class: 'chip-owner', text: dim.label }));
      chip.appendChild(h('span', { class: 'chip-pred', text: filterText(dim, f) }));
      chip.appendChild(h('button', {
        class: 'chip-x', title: `Remove the ${dim.label} filter`,
        'aria-label': `Remove the ${dim.label} filter (${filterText(dim, f)})`,
        onclick: () => removeFilter(dimId), text: '×',
      }));
      chipsBox.appendChild(chip);
    }
    // projection chip — the lens is owned state too, revertible to its previous value
    const le = lastLensEntry();
    const lensChip = h('span', { class: 'chip lens-chip' });
    lensChip.appendChild(h('span', { class: 'chip-owner', text: 'lens' }));
    lensChip.appendChild(h('span', { class: 'chip-pred', text: dimLabel(state.lens) }));
    lensChip.appendChild(h('button', {
      class: 'chip-x', text: '×',
      title: le ? `Revert projection to ${dimLabel(le.invert && lastLensFrom(le))}` : 'No previous lens to revert to',
      'aria-label': le ? `Revert projection to ${lastLensFrom(le)}` : 'No previous lens to revert to',
      disabled: !le,
      onclick: () => le && setLens(lastLensFrom(le)),
    }));
    chipsBox.appendChild(lensChip);

    // history — latest first, each entry individually revertible
    historyBox.textContent = '';
    $('#history-count').textContent = state.history.length ? `(${state.history.length})` : '';
    if (!state.history.length) {
      historyBox.appendChild(h('span', { class: 'ledger-empty', text: 'No changes yet — filters and lens switches will appear here.' }));
    }
    const latest = state.history.slice(-14).reverse();
    for (const entry of latest) {
      const row = h('div', { class: 'hist-row' + (entry.spent ? ' spent' : '') });
      row.appendChild(h('span', { class: `hist-kind ${entry.kind}`, text: entry.kind }));
      row.appendChild(h('span', { class: 'hist-label', text: entry.label }));
      row.appendChild(h('button', {
        title: 'Revert exactly this change',
        'aria-label': `Revert: ${entry.label}`,
        onclick: () => revertEntry(entry),
        text: '↩ revert',
      }));
      historyBox.appendChild(row);
    }
  }
  function lastLensFrom(entry) {
    // recover the 'from' lens recorded in the entry's label for the chip tooltip/action
    const m = entry.label.match(/lens (.+) →/);
    return m ? m[1] : null;
  }

  function renderEmpty(ws) {
    const isEmpty = ws.length === 0;
    emptyState.hidden = !isEmpty;
    tableScroll.hidden = isEmpty;
    $('#btn-empty-clear').onclick = () => {
      for (const dimId of [...state.filters.keys()]) state.filters.delete(dimId);
      pushHistory({
        kind: 'reset',
        label: 'reset — cleared all filters (from empty state)',
        invert() {
          // restore nothing structural: the removed filters were all of them; snapshot at click time
          return true;
        },
      });
      renderAll();
    };
  }

  function renderAll() {
    const ws = workingSet();
    renderHeader(ws, state.filters.size);
    renderRail();
    renderChart();
    renderTable(ws);
    renderEmpty(ws);
    renderInspector();
    renderLedger();
  }

  // ---------- global events ----------
  btnUndo.addEventListener('click', undoLatest);
  btnReset.addEventListener('click', resetAll);
  document.addEventListener('keydown', (e) => {
    if ((e.ctrlKey || e.metaKey) && !e.shiftKey && e.key.toLowerCase() === 'z') {
      e.preventDefault();
      undoLatest();
    }
  });

  // ---------- init: fully usable at first paint (data ships inline in data.js) ----------
  renderAll();
})();

