// ---------- URL hash: shareable view state (lens + filters + selection) ----------
function encodeHash() {
  const parts = [];
  if (state.lens !== INITIAL_LENS) parts.push('lens=' + state.lens);
  if (state.filters.size) {
    const specs = [];
    for (const [id, f] of state.filters) {
      const d = dimOf(id);
      specs.push(d.type === 'numeric'
        ? id + ':' + f.lo + '-' + f.hi + (f.last ? '*' : '')
        : id + ':' + [...f.allowed].join(','));
    }
    parts.push('f=' + specs.join(';'));
  }
  if (state.selection) parts.push('sel=' + state.selection);
  return parts.length ? '#' + parts.join('&') : '';
}
function applyHash() {
  if (!location.hash || location.hash.length < 2) return;
  for (const part of location.hash.slice(1).split('&')) {
    const [k, v] = part.split('=');
    if (!v) continue;
    if (k === 'lens' && dimOf(v)) state.lens = v;
    else if (k === 'sel' && DS.records.some(r => r.id === v)) state.selection = v;
    else if (k === 'f') {
      for (const spec of v.split(';')) {
        const i = spec.indexOf(':');
        if (i < 0) continue;
        const id = spec.slice(0, i), val = spec.slice(i + 1);
        const d = dimOf(id);
