    info.firedViaClick = fired;
    fired = false;
    g.dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }));
    info.firedViaDispatch = fired;
    g.removeEventListener('click', h);
    return info;
  })()`);
  console.log('probe:', JSON.stringify(probe));
  await sleep(200);
  const errs = await evalJS(ws, `window.__errs`);
  console.log('page errors:', JSON.stringify(errs));
  const state = await evalJS(ws, `({ count: document.querySelector('#working-count').textContent, chips: [...document.querySelectorAll('#filter-chips .chip-owner')].map(e=>e.textContent) })`);
  console.log('after probe clicks:', JSON.stringify(state));
  ws.close(); chrome.kill(); process.exit(0);
})().catch((e) => { console.error('ERR', e); process.exit(1); });

