'use strict';
const path = require('path');
const { spawn } = require('child_process');
const PORT = 9336;
const URL = 'file:///' + path.join(__dirname, '..').replace(/\\/g, '/') + '/index.html';
const CHROME = 'C:\\Program Files\\Google\\Chrome\\Application\\chrome.exe';
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function send(ws, method, params) {
  const id = ++send.id;
  return new Promise((resolve, reject) => {
    const onMsg = (evt) => {
      const m = JSON.parse(evt.data);
      if (m.id === id) { ws.removeEventListener('message', onMsg); m.error ? reject(new Error(method + ': ' + m.error.message)) : resolve(m.result); }
    };
    ws.addEventListener('message', onMsg);
    ws.send(JSON.stringify({ id, method, params: params || {} }));
  });
}
send.id = 0;
async function evalJS(ws, expr) {
  const r = await send(ws, 'Runtime.evaluate', { expression: expr, returnByValue: true });
  if (r.exceptionDetails) return { __exception: r.exceptionDetails.exception && r.exceptionDetails.exception.description };
  return r.result.value;
}
(async () => {
  const chrome = spawn(CHROME, ['--headless=new', '--disable-gpu', `--remote-debugging-port=${PORT}`, '--user-data-dir=' + path.join(process.env.TEMP, 'lensboard-probe3'), 'about:blank'], { stdio: 'ignore' });
  let target = null;
  for (let i = 0; i < 50 && !target; i++) {
    await sleep(200);
    try { const list = await (await fetch(`http://127.0.0.1:${PORT}/json/list`)).json(); target = list.find((t) => t.type === 'page'); } catch (e) {}
  }
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
  await send(ws, 'Page.enable'); await send(ws, 'Runtime.enable');
  await send(ws, 'Page.addScriptToEvaluateOnNewDocument', { source: `
    window.__caught = [];
    const orig = EventTarget.prototype.addEventListener;
    EventTarget.prototype.addEventListener = function (type, fn, opts) {
      if (type === 'click' && typeof fn === 'function') {
        return orig.call(this, type, function (ev) {
          try { return fn.call(this, ev); }
          catch (e) { window.__caught.push((e && e.stack) ? e.stack : String(e)); throw e; }
        }, opts);
      }
      return orig.call(this, type, fn, opts);
    };
  ` });
  await send(ws, 'Page.navigate', { url: URL });
  await sleep(1200);
  await evalJS(ws, `[...document.querySelectorAll('#rail-list .dim-row')].find(b => b.textContent.includes('Status')).click()`);
  await sleep(200);
  await evalJS(ws, `document.querySelectorAll('#lens-chart .bar-hit')[1].dispatchEvent(new MouseEvent('click', { bubbles: true, cancelable: true }))`);
  await sleep(300);
  const caught = await evalJS(ws, `window.__caught`);
  console.log('caught stacks:', JSON.stringify(caught, null, 2));
  const state = await evalJS(ws, `({ count: document.querySelector('#working-count').textContent, chips: [...document.querySelectorAll('#filter-chips .chip-owner')].map(e=>e.textContent) })`);
  console.log('state:', JSON.stringify(state));
  ws.close(); chrome.kill(); process.exit(0);
})().catch((e) => { console.error('ERR', e); process.exit(1); });

