/* Lensboard — dimensional workbench · compact professional theme */
:root {
  --bg: #edf0f4;
  --panel: #ffffff;
  --line: #e0e4ea;
  --line-strong: #c9cfd9;
  --ink: #171c26;
  --ink-2: #57606f;
  --ink-3: #8a93a3;
  --accent: #2457d6;
  --accent-ink: #1d46b2;
  --accent-mid: #7d9fec;
  --accent-soft: #e6edfc;
  --accent-faint: #f3f7ff;
  --warn: #a05a00;
  --warn-bg: #fdf3e2;
  --good: #177245;
  --bad: #b3261e;
  --radius: 8px;
}

* { box-sizing: border-box; }
html, body { height: 100%; }

body {
  margin: 0;
